<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { useRouter } from 'vue-router'; import { documentosApi, tiposApi } from '../api/resources'; import { useAuthStore } from '../stores/auth'; import { errorMessage } from '../api/client'; import type { TipoImposto } from '../types'
const router = useRouter(); const auth = useAuthStore(); const tipos = ref<TipoImposto[]>([]); const arquivo = ref<File | null>(null); const idTipoImposto = ref(''); const municipio = ref(''); const periodoVigencia = ref(''); const error = ref(''); const loading = ref(false)
onMounted(async () => { try { tipos.value = (await tiposApi()).data } catch (e) { error.value = errorMessage(e) } })
async function submit() { if (!arquivo.value || !auth.usuario) return error.value = 'Preencha todos os campos e selecione o arquivo Excel.'; loading.value = true; error.value = ''; const form = new FormData(); form.append('arquivo', arquivo.value); form.append('idTipoImposto', idTipoImposto.value); form.append('municipio', municipio.value); form.append('periodoVigencia', periodoVigencia.value); form.append('idUsuario', String(auth.usuario.id)); try { const { data } = await documentosApi.criar(form); router.push(`/documentos/${data.id}`) } catch (e) { error.value = errorMessage(e) } finally { loading.value = false } }
</script>
<template><section class="page narrow"><header class="page-header"><div><p class="eyebrow">Novo registro</p><h1>Enviar demonstrativo</h1></div><RouterLink class="secondary button" to="/documentos">Cancelar</RouterLink></header><form class="card form" @submit.prevent="submit"><p v-if="error" class="alert error">{{ error }}</p><label>Arquivo Excel (.xlsx)<input type="file" accept=".xlsx" required @change="arquivo = ($event.target as HTMLInputElement).files?.[0] || null" /></label><label>Tipo de imposto<select v-model="idTipoImposto" required><option value="" disabled>Selecione</option><option v-for="tipo in tipos" :key="tipo.id" :value="tipo.id">{{ tipo.nome }} ({{ tipo.sigla }})</option></select></label><label>Município<input v-model.trim="municipio" required /></label><label>Período de vigência<input v-model="periodoVigencia" placeholder="MM-AAAA" pattern="\d{2}-\d{4}" required /></label><button class="primary" :disabled="loading">{{ loading ? 'Enviando...' : 'Enviar documento' }}</button></form></section></template>